import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";
import type { ComponentProps, CSSProperties } from "react";
import { cn } from "./lib/cn";
import "./spirit-level.css";

export type SpiritLevelProps = Omit<ComponentProps<"div">, "children"> & {
  /** Tilt in degrees: negative leans left, positive leans right. */
  value: number;
  /** Tilt at which the bubble reaches the end of the tube. */
  max?: number;
  /** Tilt within which the surface counts as level. */
  tolerance?: number;
  label?: string;
};

/**
 * A carpenter's level. The bubble drifts to the high side and settles with one small overshoot; inside the
 * tolerance the tube takes the success colour and reads "Level". The reading is written beside the tube and
 * exposed as a meter, so the bubble is never the only carrier. Under reduced motion the bubble moves without
 * easing.
 */
export function SpiritLevel({ value, max = 10, tolerance = 0.5, label = "Level", className, style, ...props }: SpiritLevelProps) {
  const clamped = Math.max(-max, Math.min(max, value));
  const low = 0 - max;
  const level = Math.abs(value) <= tolerance;
  const text = level ? "Level" : `${Math.abs(value).toFixed(1)}° ${value > 0 ? "right" : "left"}`;
  return (
    <div
      role="meter"
      aria-label={label}
      aria-valuemin={low}
      aria-valuemax={max}
      aria-valuenow={clamped}
      aria-valuetext={level ? "Level" : `${Math.abs(value).toFixed(1)} degrees ${value > 0 ? "right" : "left"}`}
      data-slot="spirit-level"
      data-level={level ? "" : undefined}
      className={cn("grid gap-2", className)}
      style={{ "--spl-x": clamped / max, ...style } as CSSProperties}
      {...props}
    >
      <span data-slot="spl-tube" aria-hidden="true">
        <i data-slot="spl-mark" />
        <i data-slot="spl-mark" />
        <i data-slot="spl-bubble" />
      </span>
      <span data-slot="spl-read" aria-hidden="true">
        {text}
      </span>
    </div>
  );
}

/* spirit-level.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Spirit level: the bubble drifts to the high side and overshoots once; inside the tolerance the tube turns green. */
  [data-slot="spirit-level"] { width: 100%; max-width: 280px; color: var(--foreground); font-size: 13px; }
  [data-slot="spirit-level"] [data-slot="spl-tube"] { position: relative; display: block; height: 40px; container-type: inline-size; border: 1.5px solid var(--border-strong); border-radius: 20px; background: var(--muted); transition: border-color var(--duration-normal) var(--ease-out); }
  [data-slot="spirit-level"] [data-slot="spl-mark"] { position: absolute; top: 7px; bottom: 7px; left: calc(50% - 21px); width: 1.5px; border-radius: 1px; background: var(--border-strong); }
  [data-slot="spirit-level"] [data-slot="spl-mark"]:nth-child(2) { left: calc(50% + 19.5px); }
  [data-slot="spirit-level"] [data-slot="spl-bubble"] { position: absolute; top: 5px; left: calc(50% - 16px); width: 32px; height: 26px; border: 1.5px solid var(--border-strong); border-radius: 50%; background: var(--background); translate: calc(var(--spl-x) * (50cqw - 26px)) 0; transition: translate 900ms cubic-bezier(0.34, 1.45, 0.55, 1), border-color var(--duration-normal) var(--ease-out); }
  [data-slot="spirit-level"] [data-slot="spl-read"] { color: var(--muted-foreground); text-align: center; font-variant-numeric: tabular-nums; transition: color var(--duration-normal) var(--ease-out); }
  [data-slot="spirit-level"][data-level] [data-slot="spl-tube"], [data-slot="spirit-level"][data-level] [data-slot="spl-bubble"] { border-color: var(--success); }
  [data-slot="spirit-level"][data-level] [data-slot="spl-read"] { color: var(--success); }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="spirit-level"] [data-slot="spl-bubble"] { transition: none; }
  }
}
